1	/* ===== Lái xe: test lõi mạng đường DrNet (src/explore/drive/net.ts) =====
2	   Tra cao độ theo tầng (hai ô chồng mặt bằng), ngoài mọi ô, cổng đóng / mở, khung bao, loang tìm vùng tới được. */
3	import { test } from 'node:test';
4	import assert from 'node:assert/strict';
5	import { drMakeNet, drGround, drSetGate, drBounds, drReach, drAddSolids, type DrPad } from '../../src/explore/drive/net.ts';
6	
7	const flat = (y: number) => () => y;
8	const pad = (id: string, x0: number, x1: number, z0: number, z1: number, y: number, gate?: string): DrPad => {
9	  const p: DrPad = { id, kind: 'road', x0, x1, z0, z1, y: flat(y) }; if (gate) p.gate = gate; return p;
10	};
11	
12	test('drGround tách tầng', () => {
13	  const net = drMakeNet([pad('duoi', 0, 20, 0, 20, 2.6), pad('tren', 0, 20, 0, 20, 5.3)], []);
14	  assert.equal(drGround(net, 10, 10, 2.6), 2.6);
15	  assert.equal(drGround(net, 10, 10, 5.2), 5.3);
16	  assert.ok(Number.isNaN(drGround(net, 10, 10, 4.0)));
17	});
18	
19	test('ngoài mọi ô là NaN', () => {
20	  const net = drMakeNet([pad('a', 0, 20, 0, 20, 2.6)], []);
21	  assert.ok(Number.isNaN(drGround(net, 25, 10, 2.6)));
22	  assert.ok(Number.isNaN(drGround(net, 10, -0.5, 2.6)));
23	  assert.equal(drGround(net, 20, 20, 2.6), 2.6);                     // mép ô tính là trong ô
24	});
25	
26	test('cổng đóng thì ô biến mất, mở lại thì có', () => {
27	  const net = drMakeNet([pad('a', 0, 20, 0, 20, 2.6), pad('nhip', 20, 40, 0, 20, 2.6, 'g')], []);
28	  assert.equal(drGround(net, 30, 10, 2.6), 2.6);
29	  drSetGate(net, 'g', true);
30	  assert.ok(Number.isNaN(drGround(net, 30, 10, 2.6)));
31	  assert.equal(drGround(net, 10, 10, 2.6), 2.6);                     // ô không cổng vẫn còn
32	  drSetGate(net, 'g', false);
33	  assert.equal(drGround(net, 30, 10, 2.6), 2.6);
