test('vật cản thêm lúc chạy vẫn chặn (chỉ mục lưới cập nhật)', () => {
  const net = drMakeNet([pad('a', 0, 100, 0, 40, 2.6)], [wall(80, 81, 0, 40, 2.6, 4)]);
