  for (let i = 0; i < 120; i++) drStep(s, inp(), net, [], 0, DT);
  assert.ok(Math.abs(s.v - (10 - 2 * P.coast)) < 0.05, `v = ${s.v}`);
  for (let i = 0; i < 1200; i++) drStep(s, inp(), net, [], 0, DT);
